// Genere par tools/importer_scans_fr.py — NE PAS EDITER A LA MAIN.
//
// Texte francais des cartes qui n'ont PAS de scan francais : c'est le seul
// cas ou le plateau l'affiche, sous l'apercu. Les cartes fan-made n'y sont
// pas, marvelcdb ne les connait pas.
//
// Le type dit « string | undefined » parce que la plupart des codes sont
// ABSENTS : sans cela le plateau croirait tenir un texte pour chaque carte.
export const TEXTES_FR: Readonly<Record<string, string | undefined>> = {
  '01043b': "<b>Action de héros</b> : résolvez la capacité \"<b>Spéciale</b>\" de chaque amélioration [[BLACK PANTHER]] que vous contrôlez, dans n'importe quel ordre. <i>(La résolution de chaque capacité est une étape de cette séquence.)</i>",
  '01043c': "<b>Action de héros</b> : résolvez la capacité \"<b>Spéciale</b>\" de chaque amélioration [[BLACK PANTHER]] que vous contrôlez, dans n'importe quel ordre. <i>(La résolution de chaque capacité est une étape de cette séquence.)</i>",
  '01043d': "<b>Action de héros</b> : résolvez la capacité \"<b>Spéciale</b>\" de chaque amélioration [[BLACK PANTHER]] que vous contrôlez, dans n'importe quel ordre. <i>(La résolution de chaque capacité est une étape de cette séquence.)</i>",
  '01144b': "<b>Une fois révélée</b> : chaque joueur met en jeu la carte du dessus de notre deck, face cachée, engagée avec lui en tant que sbire [[Drone]].\n\n[star] <b>Boost</b>: choisissez : soit vous dépensez une ressource [mental], soit vous mettez en jeu la carte du dessus de votre deck, face cachée, engagée avec vous en tant que sbire [[Drone]].",
  '01144c': "<b>Une fois révélée</b> : chaque joueur met en jeu la carte du dessus de notre deck, face cachée, engagée avec lui en tant que sbire [[Drone]].\n\n[star] <b>Boost</b>: choisissez : soit vous dépensez une ressource [physical], soit vous mettez en jeu la carte du dessus de votre deck, face cachée, engagée avec vous en tant que sbire [[Drone]].",
  '47007b': "<b>Action de héros</b> <i>(attaque)</i> : infligez 4 dégâts à un ennemi. Si vous avez payé cette carte en utilisant 2 types de ressources différents, sonnez cet ennemi.",
  '47007c': "<b>Action de héros</b> <i>(attaque)</i> : infligez 4 dégâts à un ennemi. Si vous avez payé cette carte en utilisant 2 types de ressources différents, sonnez cet ennemi.",
  '47008b': "<b>Action de héros</b> <i>(contre)</i> : retirez 3 menaces d'une manigance. Si vous avez payé cette carte en utilisant 2 types de ressources différents, désorientez un ennemi.",
  '47008c': "<b>Action de héros</b> <i>(contre)</i> : retirez 3 menaces d'une manigance. Si vous avez payé cette carte en utilisant 2 types de ressources différents, désorientez un ennemi.",
  '50184b': "Incitation 1.\n<b>Une fois révélée</b> : placez 1 jeton Secret sur chaque carte [[Membre du Comité]].\nVous pouvez dépenser X ressources [mental] pour empêcher le placement de X de ces jetons.\n\n[star] <b>Boost</b> : résolvez la capacité « <b>Une fois révélée</b> » de cette carte.",
  '50184c': "Incitation 1.\n<b>Une fois révélée</b> : placez 1 jeton Secret sur chaque carte [[Membre du Comité]].\nVous pouvez dépenser X ressources [physical] pour empêcher le placement de X de ces jetons.\n\n[star] <b>Boost</b> : résolvez la capacité « <b>Une fois révélée</b> » de cette carte.",
  '60001a': "<i>Sens Superhumain </i> — <b>Action</b> : jouez la carte du dessus du deck [[SENS]] comme si elle était dans votre main (<i>en payant ses coûts</i>).\n<b>Interruption forcée</b> : quand une amélioration [[SENS]] est censée quitter le jeu, placez-la sous le deck [[SENS]] à la place.",
  '60002': "Attachez cette carte à un ennemi ou à une manigance.\n<b>Interruption</b> : quand vous vainquez l'ennemi attaché ou que vous retirez la dernière menace de la manigance attachée, défaussez cette amélioration → redressez votre identité.",
  '60003': "Attachez cette carte à un ennemi ou à une manigance.\n<b>Interruption</b> : quand vous vainquez l'ennemi attaché ou que vous retirez la dernière menace de la manigance attachée, défaussez cette amélioration → réduisez de 2 le coût de la prochain carte que vous jouez à cette phase.",
  '60004': "Attachez cette carte à un ennemi.\n<b>Interruption de héros</b> (<i>défense</i>) : quand l'ennemi attaché attaque, défaussez cette amélioration → cet ennemi à -3 ATQ pour cette attaque. <i>(Vous devenez la cible de cette attaque.)</i>",
  '60005': "Attachez cette carte à un ennemi.\n<b>Réponse</b> (<i>attaque</i>) : après que vous avez attaqué l'ennemi attaché, défaussez cette amélioration → infligez 3 dégâts à cet ennemi.",
  '60006': "Attachez cette carte à une manigance.\n<b>Réponse</b> (<i>contre</i>) : après que vous avez contré la manigance attachée, défaussez cette amélioration → retirez 2 menaces de cette manigance.",
  '60007': "[star] <b>Interruption forcée (héros)</b> : quand Elektra est censée subir des dégâts consécutifs, Daredevil subit ces dégâts à la place.",
  '60011': "<b>Action de héros</b> (<i>attaque</i>) : infligez 2 dégâts à chaque ennemi pour chaque amélioration attachée à cet ennemi (3 dégâts à la place si Daredevil a le trait [[aérien]]).",
  '60012': "Aucune menace ne peut être retirée de cette manigance sauf par Daredevil ou Matt Murdock.\n<b>Une fois déjouée</b> : vous pouvez déplacer n'importe quel nombre d'améliorations [[SENS]] en jeu vers d'autres cartes auxquelles elles peuvent s'attacher. Choisissez n'importe quel nombre d'améliorations du deck [[SENS]] et mettez-le en jeu. <i>(Ne mélangez pas le deck.)</i>",
  '60013': "<b>Action d'alter ego</b> : inclinez Foggy Nelson → retirez 2 menaces d'une manigance.",
  '60014': "<b>Action</b> : inclinez Karen Page → mélangez dans votre deck 1 carte du set Daredevil de votre pile de défausse. Si vous êtes sous forme d'alter ego, piochez 1 carte.",
  '60015': "<b>Réponse</b> : après qu'un personnage ou soutien [[Avocat]] a déjoué une manigance annexe, désorientez un ennemi.",
  '60016': "Matt Murdock gagne +3 REC.\n<b>Réponse</b> : après avoir récupéré, défaussez une carte d'état de votre identité.",
  '60017': "Restreint. Daredevil gagne +1 ATQ.\n<b>Action de héros</b> : renvoyez cette carte dans votre main <i>(depuis le jeu)</i> → choisissez :\n• Infligez 1 dégât à un ennemi\n• Daredevil gagne le trait [[Aérien]] jusqu'à la fin du round.",
  '60018': "<b>Action de héros</b> : inclinez cette carte et infligez 1 dégât à Daredevil → choisissez :\n• Choisissez n'importe quelle amélioration du deck [[SENS]] et jouez-la, en ignorant son coût en ressources. (<i>Ne mélangez pas le deck.</i>)\n• Redressez Daredevil.",
  '60019': "[star] <b>Réponse</b> : après que Blindspot a contré, désorientez un ennemi auquel est attachée une amélioration.",
  '60020': "<b>Action</b> : inclinez La Cape et dépensez les ressources suivantes [energy][energy] → trouvez L'Épée et mettez-la en jeu.",
  '60021': "La Cape perd chaque icône [acceleration]\n[star] Si La Cape est en jeu. L'Épée subit -1 dégât consécutif après qu'elle a utilisé un pouvoir de base.",
  '60022': "[star] <b>Interruption</b> : quand le Ghost Rider attaque un ennemi, dépensez une ressource [energy] (2 ressources [energy] à la place si cet ennemi est le méchant) → désorientez cet ennemi.",
  '60023': "[star] Réduction 1 ([[Artiste Martial]]).\n<b>Action</b> (<i>contre</i>) : retirez 1 menace d'une manigance. Retirez 1 menace d'une manigance.",
  '60024': "Victoire 0.\n<b>Une fois déjouée</b> : retirez un pion Accélération qui est en jeu.",
  '60026': "[star] Réduction 1 ([[AVOCAT] ou [[POLICE]]).\nAttachez cette carte à un sbire. 1 max par sbire.\nLe sbire attaché à -2 MNG.",
  '60027': "[star] Réduction 1 ([[Artiste martial]] ou [[espion]]).\nTemporaire. 1 max par joueur.\n<b>Réponse</b> (<i>contre</i>) : après avoir joué une carte <i>(y compris celle-ci</i>), retirez 1 menace d'une manigance.",
  '60028': "Jouez cette carte sous le contrôle de n'importe quel joueur.\n1 max par joueur.\n<b>Réponse</b> : après que vous avez contré et déjoué exactement une manigance annexe, inclinez Entraînement à la Furtivité → sonnez un ennemi.",
  '60029': "<b>Interruption</b> : quand un personnage [[MARTIAL ARTIST]] ami utilise un pouvoir de base, choisissez :\n• Inclinez Stick → ce personnage a +1 à ce pouvoir de base pour cette utilisation.\n• Ce personnage a -1 à ce pouvoir de base pour cette utilisation. Redressez Stick.",
  '60030': "1 max par joueur.\nVous pouvez jouer l'amélioration intercalée ici comme si elle était dans votre main.\n<b>Action</b> : choisissez 1 amélioration dans votre main qui peut être attachée à un sbire où à une manigance annexe. Intercalez cette amélioration sous la Planification d'Urgence (jusqu'à un maximum de 1).",
  '60031': "En Équipe (Daredevil et Elektra).\nMax 1 par deck.\nAttachez cette carte à un ennemi.\n<b>Action de héros</b> (<i>attaque</i>) : défaussez cette carte → infligez 3 dégâts à l'ennemi attaché.",
  '60032': "Donnez cette carte au joueur de Matt Murdock.\n<b>Réponse forcée</b> : après qu'une amélioration [[SENS]] entre en jeu, subissez 1 dégât.\n<b>Réponse d'alter ego</b> : après avoir récupéré, défaussez cette obligation.",
  '60033': "<b>Une fois révélée</b> : choisissez :\n• Défaussez un soutien [[INDIVIDU]] que vous contrôlez.\n• Bullseye vous attaque (<i>même si vous êtes sous forme d'alter ego</i>)",
  '60034': "<b>Interruption forcée</b> : quand Bullseye attaque, donnez-lui une carte de boost face cachée.",
  '60035': "Attachez cette carte à l'ennemi ayant l'ATQ la plus élevée.\n[star] Les attaques du personnage attaché gagnent Perçant.\n<b>Action de héros</b> : dépensez les ressources suivantes : [physical] [physical] → choisissez soit d'attacher cette carte à Elektra, soit de de la défausser.\n[star] <b>Boost</b> : si cette activation est une attaque, elle gagne Perçant.",
  '60036': "<b>Une fois révélée</b> : choisissez :\n• Retirez de la partie un allié ou un soutien [[INDIVIDU]] que vous contrôlez.\n• Bullseye vous attaque (<i>même si vous êtes sous forme d'alter ego</i>). S'il n'est pas en jeu, trouvez-le et révélez-le.",
  '60037a': "<i>Regarder et Apprendre </i> — <b>Réponse</b> : après qu'un joueur a joué un événement basique ou d'affinité, intercalez cet événement sous Echo depuis la pile de défausse du joueur. Ensuite, s'il y a plus de 3 cartes intercalées ici, défaussez toutes ces cartes sauf 3.",
  '60038': "Départ. (<i>Vous pouvez ajouter cette carte à votre main avant de piocher votre main de départ.</i>)\nVotre héros gagne +1 DEF.",
  '60039': "[star] <b>Réponse</b> : après que Daredevil a utilisé un pouvoir de base, réduisez de 1 le coût du prochain événement que vous jouez à ce round.",
  '60040a': "[star] Si vous êtes sous forme de héros, vous pouvez défaussez Réflexes Photographiques de votre main pour jouer un événement intercalé sous Echo comme s'il était dans votre main. Réduisez de 2 le coût pour jouer cet événement. Vous ne pouvez pas déclencher la capacité « Regarder et Apprendre » d'Echo pour cet événement.",
  '60040b': "[star] Si vous êtes sous forme de héros, vous pouvez défaussez Réflexes Photographiques de votre main pour jouer un événement intercalé sous Echo comme s'il était dans votre main. Réduisez de 2 le coût pour jouer cet événement. Vous ne pouvez pas déclencher la capacité « Regarder et Apprendre » d'Echo pour cet événement.",
  '60040c': "[star] Si vous êtes sous forme de héros, vous pouvez défaussez Réflexes Photographiques de votre main pour jouer un événement intercalé sous Echo comme s'il était dans votre main. Réduisez de 2 le coût pour jouer cet événement. Vous ne pouvez pas déclencher la capacité « Regarder et Apprendre » d'Echo pour cet événement.",
  '60041': "<b>Action</b> : cherchez dans la pile de défausse de n'importe quel joueur, 1 événement d'affinité, 1 événement basique ou 1 exemplaire de Réflexes Photographiques et ajoutez-le à votre main.",
  '60042': "<b>Action d'alter ego</b> : inclinez La Réz → soignez X dégâts de Maya Lopez, X étant le coût le plus élevé parmi les cartes intercalées sous elle.",
  '60043': "<b>Ressource de héros</b> : inclinez cette carte → générez une ressource [wild] pour un événement qui est en train d'être joué par n'importe que joueur.",
  '60044': "<b>Action</b> : inclinez cette carte → mélangez dans votre deck 1 événement basique ou d'affinité de votre pile de défausse. Si vous êtes sous forme d'alter ego, piochez 1 carte.",
  '60045': "Restreint.\n<b>Réponse de héros</b> (<i>attaque</i>) : après que vous avez joué un événement, inclinez le Katana d'Echo → infligez à un ennemi un nombre de dégâts égal au coût imprimé de cet événement. Cette attaque gagne Perçant.",
  '60046': "<b>Réponse de héros</b> : après que vous avez joué un événement, s'il a les traits suivants :\n• [[ATTAQUE]] — Soignez 1 dégât d'Echo.\n• [[Défense]] — Retirez 1 menace d'une manigance.\n• [[CONTRE]] — Infligez 1 dégât à un ennemi.",
  '60047': "<b>Action de héros</b> : inclinez cette carte → ajoutez à voter main un événement intercalé sous Echo.",
  '60049': "<b>Interruption de héros</b> (<i>défense/contre</i>) : quand un ennemi initie une attaque, retirez 3 menaces d'une manigance.",
  '60050': "[star] Augmentez de 1 le coût pour jouer cette carte pour chaque allié que vous contrôlez.\n<b>Action de héros</b> (<i>attaque/contre</i>) : infligez X dégâts à un ennemi et retirez X menaces d'une manigance, X étant votre DEF.",
  '60052': "Temporaire.\nVotre héros gagne +1 DEF.\nUtilisez votre DEF à la place de votre CTR et ATQ. <i>(Ignorez tous les modificateurs à vos CTR et ATQ.</i>)",
  '60053': "Tant que vous ne contrôlez pas d'allié, votre héros gagne +1 DEF et Riposte 1.",
  '60054': "1 max par joueur.\n<b>Interruption de héros</b> : quand un ennemi vous attaque (<i>avant qu'un défenseur ne soit déclaré</i>), si vous ne contrôlez pas d'allié, inclinez Seul Contre Tous → redressez votre héros.",
  '60055': "En Équipe (Daredevil et Echo). 1 max par deck.\n<b>Action</b> (<i>attaque/contre</i>) : choisissez 2 options (<i>vous pouvez choisir la même option 2 fois</i>) :\n• Infligez 3 dégâts à un ennemi.\n• Retirez 3 menaces d'une manigance.",
  '60060': "<b><i>Donnez cette carte au joueur de Maya Lopez.</i></b>\nVous ne pouvez pas infliger de dégâts au Caïd.\n<b>Une fois révélée</b> : trouvez Le Caïd et mettez-le en jeu engagé avec vous.\n<b>Réponse</b> : après que vous avez contré, placez sur cette obligation la menace retirée. S'il y a au moins 4 menaces sur cette obligation, retirez-la de la partie.",
  '60061': "<b>Interruption forcée</b> : quand le Caïd est censé attaquer le joueur de Maya Lopez, il manigance à la place.\n(<i>Sbire Némésis d'Echo.</i>)",
  '60062': "Le Caïd ne peut pas subir de dégâts.\n<b>Une fois révélée</b> : trouvez Le Caïd et mettez‑le en jeu, engagé avec vous.\n[star] <b>Boost</b> : si Le Caïd est en jeu, révélez cette manigance.",
  '60063': "Garde.\nLe Caïd ne peut pas subir de dégâts.",
  '60064': "<b>Une fois révélée (alter ego)</b> : si le Caïd est en jeu, il manigance. Sinon, cette carte gagne Renfort.\n<b>Une fois révélée (héros)</b> : infligez à un héros un nombre égal de dégâts égal à l'ATQ de votre héros.",
  '60065': "<b>Une fois révélée</b> : mettez de côté Colonne Enrobée d'Adamantium (68A).\n<b>Interruption forcée</b> : quand Bullseye s'active, chacune de ses cartes de boost gagne [boost]. Si cette activation est une attaque, elle gagne À Distance.",
  '60066': "<b>Une fois révélée</b> : trouvez Colonne Enrobée d'Adamantium et attachez-la à Bullseye.\n<b>Interruption forcée</b> : quand Bullseye s'active, chacune de ses cartes de boost gagne [boost]. Si cette activation est une attaque, elle gagne À Distance.",
  '60067': "<b>Une fois révélée</b> : trouvez Soif de Sang Malsaine et révélez-la.\n[star] <b>Interruption forcée</b> : quand Bullseye s'active, chacune de ses cartes de boost gagne [boost]. Si cette activation est une attaque, elle gagne À Distance.",
  '60068a': "Permanent.\n<b>Interruption forcée</b> : quand Bullseye est censé subir des dégâts, prévenez tous ces dégâts sauf 3. Placez sur cet attachement les dégâts prévenus. Ensuite, s'il y a au moins 6 dégâts dessus, retournez-le.",
  '60069': "Attachez cette carte à Bullseye.\n[star] <b>Interruption forcée</b> : quand Bullseye attaque, donnez-lui 1 carte de boost supplémentaire pour cette attaque. Si un personnage ami est vaincu par cette attaque, retirez ce personnage et cet attachement de la partie. Sinon, mélangez cet attachement dans le deck Rencontre.",
  '60070': "Attachez cette carte à Bulllseye.\n[star] Les attaques de Bullseye perdent À Distance et gagnent Perçant.\n<b>Réponse de héros</b> : après que votre héros a défendu contre une attaque de Bullseye, dépensez 2 ressources différentes → défaussez cet attachement.",
  '60071': "Attachez cette carte à un allié qui n'a pas déjà une Poursuite Incessante attachée. Sinon, cette carte gagne Renfort.\n<b>Interruption forcée</b> : quand le méchant est censé vous attaquer, il attaque l'allié attaché à la place et l'attaque gagne Déferlement. Si l'allié attaché est vaincu par cette attaque, retirez-le de la partie.",
  '60072': "Vilenie. (<i>Quand ce sbire s'active, donnez-lui une carte de boost.</i>)\n[star] <b>Interruption forcée</b> : quand vous résolvez les cartes de boost lors d'une attaque de Lady Bullseye, si cette attaque est non défendue, donnez-lui 1 carte de boost supplémentaire pour cette attaque.",
  '60073': "<b>Une fois révélée</b> : placez sur cette manigance annexe un nombre de menaces supplémentaires égal au numéro du stade de Bullseye.\n[star] <b>Boost</b> : après cette activation, révélez cette carte.",
  '60074': "<b>Une fois révélée (alter ego)</b> : subissez 2 dégâts indirects.\n<b>Une fois révélée (héros)</b> : choisissez : soit Bullseye s'active contre vous, soit vous retirez de la partie un allié que vous contrôlez.\n[star] <b>Boost</b> : si Bullseye est en train d'attaquer, donnez-lui une carte de boost supplémentaire et cette attaque gagne Perçant.",
  '60075': "<b>Une fois révélée</b> : choisissez : soit vous donnez cette carte au méchant en tant que carte de boost face cachée, soit vous retirez de la partie un soutien [[Individu]] que vous contrôlez.[star] <b>Boost</b> : si cette activation est une attaque, elle gagne Déferlement.",
  '60076': "<b>Une fois révélée</b> : trouvez Charge Électrique, attachez-la à Electro et placez 2[per_hero] jetons Charge dessus.\n[star] <b>Réponse forcée</b> : après qu'Electro a manigancé, placez 1 jeton Charge sur Charge Électrique.",
  '60077': "<b>Une fois révélée</b> : trouvez Charge Électrique, attachez-la à Electro et placez 2[per_hero] jetons Charge dessus.\n[star] <b>Réponse forcée</b> : après qu'Electro a manigancé, placez 1 jeton Charge sur Charge Électrique.",
  '60078': "<b>Une fois révélée</b> : placez 3 jetons Charge sur Charge Électrique.\n\n[star] <b>Réponse forcée</b> : après qu'Electro a manigancé, placez 2 jetons Charge sur Charge Électrique.",
  '60079': "Permanent.\n<b>Interruption forcée</b> : quand Electro attaque, retirez 1 jeton Charge de cet attachement → donnez une carte de boost supplémentaire à Electro pour cette attaque. Cette attaque gagne Déferlement.\n<b>Action de héros</b> : dépensez une ressource [energy] ou 2 ressources de n'importe quel type → retirez 1 jeton Charge de cet attachement.",
  '60080': "Utilisations (3 jetons Drain).\n\n<b>Une fois révélée</b> : attachez cette carte à votre identité et inclinez chaque amélioration que vous contrôlez.\n\n<b>Interruption forcée</b> : quand une amélioration que vous contrôlez est censée se redresser, vous pouvez dépenser une ressource [energy] ou 2 ressources de n'importe quel type. Si vous le faites, retirez 1 jeton Drain de cet attachement <i>(et redressez l'amélioration)</i>. Sinon, cette amélioration ne se redresse pas.",
  '60081': "<b>Interruption forcée</b> : quand Whiplash est attaqué, retirez 1 jeton Charge de Charge Électrique → défaussez la carte du dessus du deck Rencontre. Infligez 1 dégât à l'attaquant pour chaque icône de boost ([boost]) sur la carte défaussée.",
  '60082': "<b>Une fois déjouée</b> : placez 3 jetons Charge sur Charge Électrique.",
  '60083': "<b>Une fois révélée</b> : pour chaque personnage que vous contrôlez, choisissez :\n• Inclinez ce personnage.\n• Infligez 1 dégât à ce personnage (3 dégâts à la place s'il y a au moins un jeton Charge sur Charge Électrique). Retirez 1 jeton Charge de Charge Électrique.",
  '60084': "<b>Une fois révélée</b> : si aucune carte de votre main n'a d'icône de ressource [energy] imprimée, cette carte gagne Renfort. Sinon, pour chaque carte dans votre main qui a une icône de ressource [energy] imprimée, choisissez :\n• Défaussez la carte.\n• Sonnez un personnage que vous contrôlez.",
  '60085': "<b>Une fois révélée</b> : défaussez la carte du dessus de votre deck pour chaque carte que vous contrôlez. Pour chaque carte qui a une icône de ressource [energy] imprimée ainsi défaussée, choisissez :\n• Subissez 1 dégât indirect.\n• Placez 1 jeton Charge sur Charge Électrique.",
  '60086': "[star] <b>Réponse forcée</b> : après que Hammerhead a attaqué et blessé un personnage, sonnez ce personnage. Si ce personnage était déjà sonné, infligez-lui 1 dégât.",
  '60087': "Ténacité. Riposte 1.\n[star] <b>Réponse forcée</b> : après que Hammerhead a attaqué et blessé un personnage, sonnez ce personnage. Si ce personnage était déjà sonné, infligez-lui 1 dégât.",
  '60088': "Ténacité. Riposte 2.\n[star] <b>Réponse forcée</b> : après que Hammerhead a attaqué et blessé un personnage, sonnez ce personnage. Si ce personnage était déjà sonné, infligez-lui 2 dégâts.",
  '60089': "Attachez cette carte à Hammerhead.\n<b>Réponse forcée</b> : après que Hammerhead a attaqué, si le personnage attaqué n'a pas été vaincu, défaussez cet attachement → Hammerhead attaque de nouveau ce personnage.",
  '60090': "Attachez cette carte à Hammerhead.\nHammerhead gagne Robuste.\n<b>Action de héros</b> : dépensez les ressources suivantes : [energy] [mental] [physical] → défaussez cette carte.\n[star] <b>Boost</b> : donnez une carte d'état Tenace à l'ennemi en cours d'activation.",
  '60091': "[star] Le Caméléon gagne +X MNG, X étant la valeur de CTR la plus élevée parmi les personnages en jeu.\n<b>Une fois révélée</b> : Le Caméléon manigance.",
  '60092': "Garde.\n[star] La MNG des Agents de la Maggia est égale au nombre d'ennemis [[Maggia]] en jeu (y compris celui-ci).",
  '60093': "Vilenie.\n[star] <b>Interruption forcée</b> : quand le Sous-Chef de la Maggia s'active contre vous, si vous êtes sonné, donnez-lui une carte de boost supplémentaire pour cette activation.",
  '60094': "<b>Réponse forcée</b> : après qu'un sbire a été vaincu, donnez-le au méchant en tant que carte de boost face cachée.",
  '60095': "<b>Une fois révélée</b> : vainquez le sbire en jeu qui a le moins de points de vie restants. Défaussez des cartes du deck Rencontre jusqu'à ce que vous défaussiez un sbire. Révélez ce sbire.",
  '60096': "<b>Une fois révélée (alter ego)</b> : cette carte gagne Renfort.\n<b>Une fois révélée (héros)</b> : Hammerhead vous attaque. Si vous êtes sonné, Hammerhead gagne +2 ATQ pour cette attaque et elle gagne Déferlement.",
  '60097': "Chaque sbire [[Influencé]] gagne Garde.\n Chaque carte de boost du set de rencontre L'Homme Pourpre gagne :\n« [star] <b>Boost</b> : après cette activation, attribuez-vous cette carte en tant que carte Rencontre face cachée. »",
  '60098': "Chaque sbire [[Influencé]] gagne Garde et Vilenie.\n\nChaque carte de boost du set de rencontre L'Homme Pourpre gagne :\n« [star] <b>Boost</b> : après cette activation, attribuez-vous cette carte en tant que carte Rencontre face cachée. »",
  '60099': "Chaque sbire [[Influencé]] gagne Garde, Patrouille et Vilenie.\n\nChaque carte de boost du set de rencontre L'Homme Pourpre gagne :\n« [star] <b>Boost</b> : après cette activation, attribuez-vous cette carte en tant que carte Rencontre face cachée. »",
  '60100': "L'allié attaché est considéré comme un sbire [[Influencé]] ayant une boîte de texte vide. Sa MNG est égale à son CTR de base et il ne subit pas de dégâts consécutifs.\n<b>Une fois révélée</b> : attachez cette carte à l'allié ayant le coût le plus élevé que vous contrôlez et engagez-le. Sinon, cette carte gagne Renfort.",
  '60101': "Vulnérable. <i>(Défaussez ce personnage s'il est sonné ou désorienté.)</i>\n[star] Les attaques du Pompier gagnent Perçant.\n<b>Une fois vaincu</b> : défaussez le soutien ou l'amélioration en jeu qui a le coût le plus élevé.",
  '60102': "Vulnérable. (<i>Défaussez ce personnage s'il est sonné ou désorienté.</i>)\n<b>Une fois vaincu</b> : placez 3 menaces sur la manigance principale.",
  '60103': "Patrouille. Vulnérable. <i>(Défaussez ce personnage s'il est sonné ou désorienté.)</i>\n<b>Une fois vaincu</b> : défaussez l'allié en jeu qui a l'ATQ la plus élevée <i>(parmi les alliés)</i>.",
  '60104': "Vulnérable. (<i>Défaussez ce personnage s'il est sonné ou désorienté.</i>)\n<b>Une fois vaincu</b> : infligez 3 dégâts à l'identité du joueur qui a vaincu ce sbire.",
  '60105': "Utilisations (3 jetons Ordre).\n<b>Action forcée</b> : retirez 1 jeton Ordre de cette carte et inclinez-la → infligez 2 dégâts à un héros ou à un allié.",
  '60106': "Utilisations (3 jetons Ordre).\n\n<b>Action forcée</b> : retirez 1 jeton Ordre de cette carte et inclinez-la → donnez une carte d'état Tenace au méchant.",
  '60107': "Utilisations (3 jetons Ordre).\n<b>Action forcée</b> : retirez 1 jeton Ordre de cette carte et inclinez-la → placez 2 menaces sur la manigance principale.",
  '60108': "[star] Entrave 3[per_hero].\nChaque sbire gagne le trait [[Influencé]].",
  '60109': "<b>Une fois révélée</b> : choisissez un sbire [[Influencé]] dans la pile de défausse Rencontre et révélez-le. Sinon, cette carte gagne Renfort.",
  '60110a': "<b>Interruption forcée</b> : quand Mary Typhoïde est censée être vaincue, placez 1 pion Dégât sur Psyché Perturbée à la place et réinitialisez ses points de vie à 10[per_hero].",
  '60111a': "Ténacité.\n\n<b>Interruption forcée</b> : quand Mary Typhoïde est censée être vaincue, placez 1 pion Dégât sur Psyché Perturbée à la place et réinitialisez ses points de vie à 13[per_hero].",
  '60112': "<b>Mise en place</b> : mettez en jeu le méchant sur une face sélectionnée au hasard <i>(et révélez-le)</i>.\n<b>Interruption forcée</b> : quand la phase du Méchant se termine, retournez le méchant.\nS'il y a au moins 3 pions sur cet environnement, les joueurs remportent la partie !",
  '60113a': "Permanent. Mise en Place.\n[star] En mode expert, cette carte gagne Entrave 3[per_hero].\n<b>Une fois déjouée</b> : placez 1 pion Menace sur Psyché Perturbée. Retournez cette manigance annexe.",
  '60114': "Attachez cette carte au méchant.\n\n<b>Action de héros</b> : dépensez les ressources suivantes : [physical][physical] → défaussez cette carte.\n\n[star] <b>Boost</b> : si Mary Typhoïde est en cours d'activation, subissez 3 dégâts indirects. Inclinez chaque personnage blessé par cet effet.",
  '60115': "<b>Une fois révélée</b> : si l'attachement Mary Walker est en jeu, retournez-le et révélez Gagner la Confiance. Le méchant manigance.[star] <b>Boost</b> : si Mary Typhoïde est en cours d'activation, infligez 3 dégâts à un allié que vous contrôlez.",
  '60116': "<b>Une fois révélée</b> : infligez 1 dégât à chaque personnage que vous contrôlez. Vous êtes sonné.\n[star] <b>Boost</b> : si Mary Typhoïde est en cours d'activation, vous êtes sonné.",
  '60117': "Attachez cette carte au méchant.\n\n<b>Interruption forcée</b> : quand le méchant est censé subir n'importe quelle quantité de dégât, placez-les sur cette carte à la place. Ensuite, s'il y a au moins 5 dégâts sur l'Armure Assemblée (au moins 8 en mode expert), défaussez-la.\n[star] <b>Boost</b> : si Bloody Mary est en cours d'activation, vous êtes désorienté.",
  '60118': "<b>Une fois révélée</b> : si l'attachement Mary Walker est en jeu, retournez-le et révélez Gagner la Confiance. Le méchant vous attaque <i>(même si vous êtes sous forme d'alter ego)</i>.[star] <b>Boost</b> : si Bloody Mary est en cours d'activation, subissez 2 dégâts.",
  '60119': "Renfort.\n<b>Une fois révélée</b> : donnez une carte d'état Tenace au méchant.\n[star] <b>Boost</b> : si Bloody Mary est en cours d'activation, donnez-lui une carte d'état Tenace.",
  '60120': "Garde. Ténacité.\n\n[star] <b>Boost</b> : donnez une carte de boost supplémentaire à l'ennemi en cours d'activation.",
  '60121a': "<b>Contenu</b> : le méchant [[Subordonné]] (voir le Livret de Règles, page 5). Le set du méchant. Les sets Cambriolage du Musée d'Art et Standard. Deux sets modulaires (Policiers et Le Hibou).\n\n<b>Mise en place</b> : trouvez les 4 attachements [[Art]] du set Cambriolage du Musée d'Art, prenez-en 1 au hasard et attachez-le au méchant. Mélangez les 3 autres dans le deck Rencontre.",
  '60122': "Renfort.\nAttachez cette carte au méchant.\n<b>Réponse forcée</b> : après que cette carte a été attachée à un personnage, désorientez ce personnage.\n<b>Action de héros</b> : dépensez une ressource [mental] ou inclinez votre héros → attachez cette carte à votre héros.",
  '60123': "Renfort.\nAttachez cette carte au méchant.\nLe personnage attaché gagne Robuste.\n<b>Action de héros</b> : dépensez une ressource [star] ou inclinez votre héros → attachez cette carte à votre héros.",
  '60124': "Renfort.\nAttachez cette carte au méchant.\n<b>Réponse forcée</b> : après que cette carte a été attachée à un personnage, donnez-lui une carte d'état Tenace.\n<b>Action de héros</b> : dépensez une ressource [physical] ou inclinez votre héros → attachez cette carte à votre héros.",
  '60125': "Renfort.\nAttachez cette carte au méchant.\n<b>Réponse forcée</b> : après que cette carte a été attachée à un personnage, sonnez-le.\n<b>Action de héros</b> : dépensez une ressource [energy] ou inclinez votre héros → attachez cette carte à votre héros.",
  '60126': "<b>Une fois révélée</b> : cherchez un attachement [[Art]] dans le deck Rencontre ou la pile de défausse Rencontre et attachez-le au méchant. Si vous ne pouvez pas le faire, déplacez un attachement [[Art]] d'une identité vers le méchant.\n[star] <b>Boost</b> : déplacez un attachement [[Art]] d'une identité vers le méchant.",
  '60127': "<b>Une fois révélée</b> : vous pouvez dépenser les ressources suivantes : [physical][physical][physical] pour déplacer un attachement [[Art]] du méchant vers votre identité. Sinon, déplacez un attachement [[Art]] d'une identité vers le méchant et cette carte gagne Renfort.",
  '60128a': "<b>Contenu</b> : le méchant [[Subordonné]] (voir le Livret de Règles, page 5). Le set du méchant. Les sets La Poursuite et Standard. Deux sets modulaires (Policiers et Conduite).\n<b>Mise en place</b> : placez 1 jeton Vitesse sur cette manigance (2 jetons à la place en mode expert). Attachez au méchant l'attachement En Tête (129A).",
  '60129a': "Permanent. Attachez cette carte au méchant.\nS'il n'y a pas de menace sur la manigance principale, retournez cet attachement.\n[star] Les attaques du méchant attaché gagnent À Distance.\n<b>Interruption forcée</b> : quand le méchant est censé subir n'importe quelle quantité de dégâts, retirez la même quantité de menace de la manigance principale à la place <i>(en ignorant les icônes de crise [crisis])</i>.",
  '60130': "Garde. Patrouille.\nSi le nombre de jetons Vitesse sur la manigance principale est d'au moins :\n• 3 – Ce sbire gagne Ténacité.\n• 6 – Ce sbire gagne également Coup Rapide.\n• 9 – Ce sbire gagne également Renfort.",
  '60131': "[star] Entrave 1[per_hero].\nLe méchant ne peut pas subir de dégâts.",
  '60132': "<b>Une fois révélée</b> : pour chaque jeton Vitesse sur la manigance principale, choisissez :\n• Dépensez 1 ressource de n'importe quel type.\n• Placez 1 menace sur la manigance principale.",
  '60133': "<b>Une fois révélée</b> : pour chaque jeton Vitesse sur la manigance principale, choisissez :\n• Inclinez un personnage que vous contrôlez.\n• Subissez 1 dégât indirect.",
  '60134a': "<b>Contenu</b> : le méchant [[Subordonné]] <i>(voir le Livret de Règles, page 5)</i>. Le set du méchant. Les sets Racket en Bande Organisée et Standard. Deux sets modulaires <i>(Désastres et Mafia des Survêtes)</i>.\n<b>Mise en place</b> : chaque joueur choisit une seule manigance principale Racket en Bande Organisée (il la sélectionne aléatoirement en mode expert), la place dans sa zone de jeu, et la retourne pour afficher sa face 1B. Mettez de côté chaque manigance principale inutilisée, hors jeu.",
  '60135a': "<b>Contenu</b> : le méchant [[Subordonné]] <i>(voir le Livret de Règles, page 5)</i>. Le set du méchant. Les sets Racket en Bande Organisée et Standard. Deux sets modulaires <i>(Désastres et Mafia des Survêtes)</i>.\n<b>Mise en place</b> : chaque joueur choisit une seule manigance principale Racket en Bande Organisée (il la sélectionne aléatoirement en mode expert), la place dans sa zone de jeu, et la retourne pour afficher sa face 1B. Mettez de côté chaque manigance principale inutilisée, hors jeu.",
  '60136a': "<b>Contenu</b> : le méchant [[Subordonné]] <i>(voir le Livret de Règles, page 5)</i>. Le set du méchant. Les sets Racket en Bande Organisée et Standard. Deux sets modulaires <i>(Désastres et Mafia des Survêtes)</i>.\n<b>Mise en place</b> : chaque joueur choisit une seule manigance principale Racket en Bande Organisée (il la sélectionne aléatoirement en mode expert), la place dans sa zone de jeu, et la retourne pour afficher sa face 1B. Mettez de côté chaque manigance principale inutilisée, hors jeu.",
  '60137a': "<b>Contenu</b> : le méchant [[Subordonné]] <i>(voir le Livret de Règles, page 5)</i>. Le set du méchant. Les sets Racket en Bande Organisée et Standard. Deux sets modulaires <i>(Désastres et Mafia des Survêtes)</i>.\n<b>Mise en place</b> : chaque joueur choisit une seule manigance principale Racket en Bande Organisée (il la sélectionne aléatoirement en mode expert), la place dans sa zone de jeu, et la retourne pour afficher sa face 1B. Mettez de côté chaque manigance principale inutilisée, hors jeu.",
  '60138a': "<b>Contenu</b> : le méchant [[Subordonné]] <i>(voir le Livret de Règles, page 5)</i>. Le set du méchant. Les sets Racket en Bande Organisée et Standard. Deux sets modulaires <i>(Désastres et Mafia des Survêtes)</i>.\n<b>Mise en place</b> : chaque joueur choisit une seule manigance principale Racket en Bande Organisée (il la sélectionne aléatoirement en mode expert), la place dans sa zone de jeu, et la retourne pour afficher sa face 1B. Mettez de côté chaque manigance principale inutilisée, hors jeu.",
  '60139': "<b>Une fois révélée</b> : mettez en jeu le Gérant de Magasin sous votre contrôle. Cette carte gagne Renfort.\n\n<b>Interruption forcée</b> : quand cet allié quitte le jeu, placez 4 menaces sur la manigance principale de votre zone de jeu.",
  '60140': "[star] <b>Réponse forcée</b> : après que L'Homme-Taureau a attaqué, placez sur la manigance principale un nombre de menaces égal aux dégâts en excès infligés par cette attaque.[star] <b>Boost</b> : si cette activation est une attaque, placez sur la manigance principale un nombre de menaces égal aux dégâts en excès infligés par cette attaque.",
  '60141': "<b>Une fois révélée</b>  : échangez votre manigance principale avec une manigance principale mise de côté, prise au hasard. Placez les menaces de la manigance précédente sur la nouvelle manigance.[star] <b>Boost</b> : résolvez la capacité « <b>Une fois révélée</b> » de cette carte.",
  '60142a': "<b>Contenu</b> : le méchant [[Subordonné]] (voir le Livret de Règles, page 5). Le set du méchant. Les sets L'Évasion du Raft et Standard. Deux sets modulaires (Le Hibou et Tombstone).\n<b>Mise en place</b> : attachez le Passe-Partout au méchant. Chaque joueur défausse des cartes du deck Rencontre jusqu'à ce qu'il défausse un sbire [[Prisonnier]], puis le révèle.",
  '60143': "Attachez cette carte au méchant.\nPermanent.\n[star] <b>Réponse forcée</b> : après que le méchant a manigancé contre vous, attribuez-vous chaque carte de boost de cette activation qui est un [[sbire]], en tant que carte Rencontre face cachée.",
  '60144': "Vilenie.\n\n<b>Interruption forcée</b> : quand L'Homme Absorbant vous attaque, intercalez sous ce sbire la carte du dessus de votre deck. Il gagne +1 ATQ pour cette attaque pour chaque type de ressource différent ([energy], [physical], [mental] et [wild]) parmi les cartes intercalées sous lui.",
  '60145': "Vilenie.\nChaque allié avec de la menace sur lui est considéré comme un sbire <b>Trahi</b> ayant une boîte de texte vide. Sa MNG est égale à son CTR de base et il ne subit pas de dégâts consécutifs.\n<i>Une fois révélée</i> — <b>Une fois révélée</b> : placez 1 menace sur un allié qui n'en a pas. Il engage son contrôleur.",
  '60146': "Vilenie.\n\n[star] <b>Réponse forcée</b> : après que Drang vous a attaqué, placez 1 jeton Salve sur lui. Ensuite, subissez 1 dégât indirect pour chaque jeton Salve sur Drang.",
  '60147': "Vilenie.\n[star] <b>Réponse forcée</b> : après que Mysterio vous a attaqué, attribuez-vous chaque carte de boost de cette activation qui est une traîtrise, en tant que carte Rencontre face cachée.",
  '60148': "Vilenie.\n\n<b>Interruption forcée</b> : quand Proxima Minuit vous attaque, choisissez : soit vous placez 1 menace sur la manigance principale, soit Proxima Minuit gagne +2 ATQ pour cette attaque.",
  '60149': "Ténacité. Vilenie.\n[star] Les attaques de Rhino gagnent Déferlement.\n[star] <b>Boost</b> : donnez une carte d'état Tenace à l'ennemi en cours d'activation.",
  '60150': "Vous ne pouvez pas contrer, attaquer ou passer sous forme d'alter ego.\n\n<b>Action de héros</b> : dépensez 3 ressources de n'importe quel type ou inclinez des personnages que vous contrôlez pour un total de 3 CTR ou plus → défaussez cette obligation.\n\n[star] <b>Boost</b> : révélez cette carte.",
  '60151a': "<b>Contenu</b> : le méchant [[Subordonné]] (voir le Livret de Règles, page 5). Le set du méchant. Les sets Arrêtez les Rotatives ! et Standard. Deux sets modulaires (Tombstone et Mafia des Survêtes).\n<b>Mise en place</b> : mettez en jeu l'environnement Daily Bugle. Chaque joueur prend au hasard un soutien [[Daily Bugle]] et le met en jeu sous son contrôle. Retirez de la partie chaque soutien [[Daily Bugle]] restant.",
  '60152': "<b>Action d'alter ego</b> : inclinez un soutien [[Daily Bugle]] que vous contrôlez → placez 1 jeton Endurance sur ce soutien. <i>(N'importe quel joueur peut déclencher cette capacité).</i>",
  '60153': "Utilisations (3 jetons Endurance).\n<b>Action</b> : inclinez Ben Urich et retirez-lui 1 jeton Endurance → regardez les 2 cartes du dessus du deck Rencontre. Vous pouvez défausser 1 de ces cartes. <i>(Remettez les autres dans le même ordre.)</i>",
  '60154': "Utilisations (3 jetons Endurance).\n<b>Interruption</b> : quand une carte de boost est retournée face visible, inclinez Betty Brant et retirez-lui 1 jeton Endurance → annulez les icônes de boost et la capacité « <b>Boost</b> » de cette carte. Donnez à l'ennemi en cours d'activation une autre carte de boost pour cette activation.",
  '60155': "Utilisations (3 jetons Endurance).\n\n<b>Action</b> : inclinez J. Jonah Jameson, retirez-lui 1 jeton Endurance et attribuez-vous 1 carte Rencontre face cachée → piochez 2 cartes.",
  '60156': "Utilisations (3 jetons Endurance).\n\n<b>Réponse</b> : après qu'une carte Rencontre face cachée a été attribuée à un joueur, inclinez Robbie Robertson et retirez-lui 1 jeton Endurance → regardez cette carte Rencontre. Vous pouvez la défausser et attribuer à ce joueur une autre carte Rencontre face cachée.",
  '60157': "Les soutiens [[Daily Bugle]] ne peuvent pas se redresser.\n<b>Une fois révélée</b> : inclinez chaque soutien [[Daily Bugle]].",
  '60158': "<b>Une fois révélée</b> : choisissez :\n• Inclinez un soutien [[Daily Bugle]] (sous le contrôle de n'importe quel joueur) et retirez-lui 1 jeton Endurance.\n• Placez 2 menaces sur la manigance principale.\n[star] <b>Boost</b> : inclinez un soutien [[Daily Bugle]] (sous le contrôle de n'importe quel joueur).",
  '60159a': "Robuste.\nLe Caïd ne peut pas subir de dégâts ni avoir d'améliorations attachées. <i>(Les joueurs doivent récupérer le Soutien des Citoyens pour l'affronter directement.)</i>\n<b>Interruption forcée</b> : quand Le Caïd est censé vous attaquer, il manigance à la place.",
  '60160a': "Robuste.\nLe Caïd ne peut pas subir de dégâts ni avoir d'améliorations attachées. <i>(Les joueurs doivent récupérer le Soutien des Citoyens pour l'affronter directement.)</i>\n[star] <b>Interruption forcée</b> : quand Le Caïd est censé vous attaquer, il manigance à la place.",
  '60161a': "<b>Contenu</b> : Le Caïd (A1). <i>(Le Caïd (B1) en mode expert.)</i> Le set de rencontre du Caïd. Deux sets de rencontre modulaires (<i>Tombstone</i> et <i>Mafia des Survêtes</i>).\n<b>Mise en place</b> : chaque joueur révèle son sbire Némésis mis de côté. Chaque joueur dont le sbire Némésis partage un titre avec un personnage en jeu retire son sbire Némésis de la partie à la place. Ensuite, il trouve un sbire [[SUBORDONNÉ]] qui n'est pas en jeu et le révèle.",
  '60162a': "<b>Une fois révélée</b> : chaque joueur trouve son sbire Némésis et le révèle. Chaque joueur dont le sbire Némésis n'est pas entré en jeu par cet effet trouve un sbire [[Subordonné]] qui n'est pas en jeu et le révèle. En mode expert, le premier joueur trouve et révèle la manigance annexe Crime Organisé.",
  '60163a': "<b>Réponse forcée</b> : après qu'un sbire a été vaincu, placez 1 jeton Soutien sur cet environnement.\n\n<b>Interruption forcée</b> : quand la phase du Méchant commence, s'il y a au moins 2[per_hero]+2 jetons Soutien sur cet environnement, retournez Le Caïd et passez au stade 2A de la manigance principale. Ensuite, retournez cet environnement.",
  '60164': "Attachez cette carte à votre héros si Le Caïd a le trait [[Artiste Martial]]. Sinon, cette carte gagne Renfort.\nUtilisations (3 jetons Prise).\nVous ne pouvez pas passer sous forme d'alter ego.\n<b>Interruption forcée</b> : quand vous êtes censé contrer ou attaquer, retirez 1 jeton Prise de cette carte à la place.",
  '60165': "<b>Une fois révélée</b> : attachez cette carte au Caïd et donnez-lui une carte de boost face cachée.\n\n<b>Action de héros</b> : défaussez un événement [[Contre]] de votre main → défaussez James Wesley. Le Caïd manigance.\n\n[star] <b>Boost</b> : attachez cette carte au Caïd.",
  '60166': "<b>Une fois révélée</b> : attachez cette carte au Caïd. Vous êtes sonné.\n\n<b>Réponse forcée</b> : après que Le Caïd a attaqué et blessé un héros, sonnez ce héros. Si un héros est sonné par cet effet, défaussez cet attachement.\n[star] <b>Boost</b> : vous êtes sonné. Si vous étiez déjà sonné, subissez 1 dégât.",
  '60167': "Attachez cette carte au Caïd s'il a le trait [[Artiste Martial]]. Sinon, cette carte gagne Renfort.\nLe Caïd gagne Riposte 1.\n<b>Interruption forcée</b> : quand Le Caïd est censé subir n'importe quelle quantité de dégâts, placez ces dégâts sur cette carte à la place. Ensuite, s'il y a au moins 8 dégâts dessus, défaussez Montagne de Muscle.",
  '60168': "<b>Une fois révélée</b> : attachez cette carte au Caïd. Vous êtes désorienté.\n<b>Action de héros</b> : défaussez un événement [[Attaque]] de votre main → défaussez Vanessa Fisk. Le Caïd vous attaque.\n[star] <b>Boost</b> : vous êtes désorienté. Si vous étiez déjà désorienté, placez 1 menace sur la manigance principale.",
  '60169': "Vilenie.\n\nTant qu'elle a au moins 4 menaces sur elle, Black Cat est considérée comme étant une alliée qui subit 2 dégâts consécutifs après qu'elle a attaqué ou contré.\n<b>Action de héros</b> : dépensez une ressource [mental] → placez 1 menace sur cette carte. S'il y a 4 menaces dessus, prenez le contrôle de Black Cat en tant qu'alliée.",
  '60170': "Vilenie.\n<b>Interruption forcée</b> : quand Diamondback vous attaque, subissez 1 dégât.\n[star] <b>Boost</b> : subissez 1 dégât.",
  '60171': "Entre en jeu avec 1 jeton Tâche sur lui.\n<b>Interruption forcée</b> : quand La Tâche est censée subir des dégâts d'une attaque, s'il a au moins 1 jeton Tâche sur lui, retirez-lui 1 jeton Tâche et infligez ces dégâts à l'attaquant à la place. Sinon, placez 1 jeton Tâche ici.",
  '60172': "Entre en jeu avec 2 jetons Échasse sur lui.\n[star] L'Homme aux Échasses gagne +1 MNG et +1 ATQ pour chaque jeton Échasse sur lui.\n<b>Interruption forcée</b> : quand L'Homme aux Échasses est censé subir n'importe quelle quantité de dégâts, retirez-lui 1 jeton Échasse à la place.",
  '60173': "<b>Une fois déjouée</b> : le joueur qui a déjoué cette manigance place 3 menaces sur la manigance annexe de sa Némésis. Si elle n'est pas en jeu, il la trouve et la révèle.",
  '60174': "Chaque sbire gagne +2 points de vie.",
  '60175': "<b>Une fois révélée</b> : révélez une carte prise au hasard dans votre set de Némésis mis de côté. Si aucune carte n'est révélée par cet effet, cette carte gagne Renfort.[star] <b>Boost</b> : donnez à ce personnage une carte prise au hasard dans votre set de Némésis mis de côté, en tant que carte de boost supplémentaire.",
  '60176': "<b>Une fois révélée</b> : votre sbire Némésis s'active contre vous. Si votre sbire Némésis n'est pas en jeu, trouvez-le et révélez-le. Si vous ne pouvez pas le trouver, trouvez un sbire [[Subordonné]] qui n'est pas en jeu et révélez-le.\n[star] <b>Boost</b> : si cette activation est une attaque, elle gagne Déferlement.",
  '60177': "Utilisations (2 jetons Civil).\n\n<b>Action de héros</b> : dépensez les ressources suivantes : [mental] [mental] ou inclinez un héros ou allié que vous contrôlez → retirez 1 jeton Civil de cet environnement (2 jetons à la place si vous avez incliné un personnage [[Mystique]]).",
  '60178': "Utilisations (2 jetons Civil).\n\n<b>Action de héros</b> : dépensez les ressources suivantes : [energy] [energy] ou inclinez un héros ou allié que vous contrôlez → retirez 1 jeton Civil de cet environnement (2 jetons à la place si vous avez incliné un personnage [[Aérien]]).",
  '60179': "Utilisations (2 jetons Civil).\n\n<b>Action de héros</b> : dépensez les ressources suivantes : [physical][physical] ou inclinez un héros ou allié que vous contrôlez → retirez 1 jeton Civil de cet environnement (2 jetons à la place si vous avez incliné un personnage qui a une carte d'état Tenace).",
  '60180': "[star] Entrave 2[per_hero].\n<b>Réponse forcée</b> : après que n'importe quelle quantité de menaces a été retirée de cette manigance annexe, placez-y 1 menace.",
  '60181': "Péril.\n<b>Une fois révélée</b> : placez 1 jeton Civil sur un environnement [[Désastre]]. Si aucun jeton n'a été placé par cet effet, cherchez un environnement [[Désastre]] dans le deck Rencontre ou la pile de défausse Rencontre et révélez-le.[star] <b>Boost</b> : placez 1 jeton Civil sur un environnement [[Désastre]].",
  '60182': "Coup Rapide. Vulnérable.\n[star] <b>Interruption forcée</b> : quand le Policier est censé manigancer, il attaque le méchant à la place.\n<b>Une fois vaincu</b> : placez 2 menaces sur la manigance principale.",
  '60183': "Coup Rapide. Vulnérable.\n<b>Une fois vaincu</b> : le joueur qui a vaincu ce sbire s'attribue une carte Rencontre face cachée.\n[star] <b>Boost</b> : infligez 2 dégâts indirects.",
  '60184': "<b>Action de héros</b> : défaussez des cartes du deck Rencontre jusqu'à ce qu'un sbire [[Police]] soit défaussé et mettez-le en jeu engagé avec vous. Défaussez cette obligation.",
  '60185': "[star] Entrave 1[per_hero].\nChaque sbire [[Police]] gagne Garde et Patrouille.\n<b>Une fois révélée</b> : cherchez un sbire [[Police]] dans le deck Rencontre ou la pile de défausse Rencontre et révélez-le.",
  '60186': "Attachez cette carte à l'ennemi ayant l'ATQ la plus élevée et qui n'a pas d'attachement [[Véhicule]]. Sinon, cette carte gagne Renfort.\n<b>Interruption forcée</b> : quand le personnage attaché est censé subir n'importe quelle quantité de dégâts, placez-les sur cette carte à la place. S'il y a au moins 4 dégâts sur la Voiture de Sport, défaussez-la.",
  '60187': "Attachez cette carte à l'ennemi ayant la MNG la plus élevée et qui n'a pas d'attachement [[Véhicule]]. Sinon, cette carte gagne Renfort.\n<b>Interruption forcée</b> : quand le personnage attaché est censé subir n'importe quelle quantité de dégâts, placez-les sur cette carte à la place. S'il y a au moins 3 dégâts sur la Moto, défaussez-la.",
  '60188': "Attachez cette carte à l'ennemi ayant le moins de points de vie restants et qui n'a pas d'attachement [[Véhicule]]. Sinon, cette carte gagne Renfort.\n<b>Interruption forcée</b> : quand le personnage attaché est censé subir n'importe quelle quantité de dégâts, placez-les sur cette carte à la place. S'il y a au moins 6 dégâts sur le Fourgon Utilitaire, défaussez-le.",
  '60189': "[star] Entrave 2[per_hero].\n<b>Interruption forcée</b> : quand un personnage ayant un attachement [[VÉHICULE]] est censé :\n• ajouter de la menace à une manigance, cette menace est ajoutée à l'Embouteillage à la place.\n• retirer de la menace d'une manigance, cette menace est retirée de l'Embouteillage à la place.",
  '60190': "<b>Une fois révélée</b> : défaussez des cartes du deck Rencontre jusqu'à ce qu'un attachement [[Véhicule]] soit défaussé et révélez-le. Si votre identité n'a pas d'attachement [[Véhicule]], vous pouvez dépenser 3 ressources d'un même type pour attacher l'attachement défaussé à votre identité à la place.",
  '60191': "Attachez cette carte à un ennemi non-[[Aérien]]. Sinon, cette carte gagne Renfort.\nL'ennemi attaché gagne [[Aérien]].\n<b>Action de héros</b> : défaussez un événement <b>Attaque</b> de votre main → défaussez cet attachement.",
  '60192': "[star] Les attaques de Monsieur Poisson gagnent Perçant et À Distance.\n<b>Une fois révélée</b> : Monsieur Poisson engage le joueur dont l'identité a le moins de points de vie restants.",
  '60193': "Coup Rapide.\n[star] Les attaques du Hibou gagnent Perçant.[star] <b>Boost</b> : si cette activation est une attaque, elle gagne Perçant.",
  '60194': "<b>Une fois révélée (alter ego)</b> : le méchant et chaque sbire engagé avec vous manigancent. Chaque ennemi [[Aérien]] gagne +2 MNG pour cette activation.\n<b>Une fois révélée (héros)</b> : le méchant et chaque sbire engagé avec vous vous attaquent. Chaque ennemi [[Aérien]] gagne +2 ATQ pour cette activation.",
  '60195': "Attachez cette carte au sbire ayant les points de vie de base les plus élevés et donnez-lui une carte d'état Tenace. Sinon, cette carte gagne Renfort.\n<b>Réponse forcée</b> : après que le sbire attaché a manigancé, désorientez l'identité du premier joueur et défaussez Froid Comme la Glace.",
  '60196': "Attachez cette carte au sbire ayant les points de vie de base les plus élevés et donnez-lui une carte d'état Tenace. Sinon, cette carte gagne Renfort.\n<b>Réponse forcée</b> : après que le sbire attaché a attaqué, sonnez le personnage attaqué et défaussez Dur Comme le Marbre.",
  '60197': "Vilenie.\n<b>Une fois révélée</b> : cherchez dans le deck Rencontre ou la pile de défausse Rencontre un attachement pouvant être attaché à un sbire et attachez-le au Scarabée.",
  '60198': "Coup Rapide.[star] <b>Boost</b> : donnez une carte d'état Tenace au méchant.",
  '60199': "<b>Réponse forcée</b> : après le début de la phase du Méchant, infligez 3 dégâts indirects au premier joueur. Pour chaque allié ainsi vaincu, retirez 1[per_hero] menace de cette manigance annexe.",
  '60200': "Collaboration ([[Survêtes]]).\n<b>Une fois révélée</b> : placez 1 pion Accélération sur ce sbire.\n[star] <b>Réponse forcée</b> : après qu'Ivan Banionis a manigancé, placez 1 pion Accélération sur lui.",
  '60201': "Collaboration ([[Survêtes]]). Vilenie.\n[star] <b>Réponse forcée</b> : après que Kazimierz le Clown a manigancé, donnez-lui 1 carte de boost face cachée.",
  '60202': "Riposte 2. Collaboration ([[Survêtes]]). Vulnérable.\n<b>Une fois vaincu</b> : intercalez cette carte sous la manigance annexe Mafia des Survêtes. Sinon, sonnez et désorientez le personnage qui a vaincu le Mafieux des Survêtes.",
  '60203': "Collaboration ([[Survêtes]]). Vulnérable.\n<b>Une fois vaincu</b> : intercalez cette carte sous la manigance annexe Mafia des Survêtes. Sinon, mélangez cette carte dans le deck Rencontre.",
  '60204': "<b>Une fois révélée</b> : défaussez des cartes du dessus du deck Rencontre jusqu'à ce qu'un sbire [[Survêtes]] soit défaussé et intercalez-le sous cette manigance.\n<b>Réponse forcée</b> : après qu'un joueur a révélé un sbire [[Survêtes]] du deck Rencontre, ce joueur révèle 1 sbire intercalé sous cette manigance.",
  '60205a': "<b>Mise en place</b> : donnez à chaque identité une carte d'état Tenace.",
  '60206a': "<b>Mise en place</b> : après avoir résolu les mulligans, chaque joueur peut chercher une amélioration dans son deck ou sa pile de défausse et l'ajouter à sa main. En mode expert, chaque joueur qui l'a fait défausse 1 carte de sa main.",
  '60207a': "<b>Mise en place</b> : après avoir résolu les mulligans, chaque joueur peut chercher un soutien dans son deck ou sa pile de défausse et l'ajouter à sa main. En mode expert, chaque joueur qui l'a fait défausse 1 carte de sa main.",
  '60208a': "<b>Mise en place</b> : après avoir résolu les mulligans, chaque joueur peut chercher un allié dans son deck ou sa pile de défausse et l'ajouter à sa main. En mode expert, chaque joueur qui l'a fait défausse 1 carte de sa main.",
  '60209a': "<b>Mise en place</b> : chaque joueur met en jeu 1 soutien [[Daily Bugle]] (qui n'a pas été retiré de la campagne) du set de rencontre Arrêtez les Rotatives !.",
  '60210a': "<b>Mise en Place</b>. Victoire -1.\n\n[star] <b>Réponse forcée</b> : après avoir révélé un sbire, retirez tous les dégâts sur cette alliée et retournez sa carte.",
  '61001a': "[star] <i>Rassembler des Preuves</i> — <b>Réponse</b> : après que vous avez utilisé un pouvoir de base, placez 1 jeton Preuve sur Alias Investigations.",
  '61002': "Permanent.\n<b>Réponse</b> : après qu'une manigance annexe a été déjouée, inclinez ce soutien → placez 2 jetons Preuve dessus. Ensuite, vous pouvez retirer de ce soutien un nombre de jetons Preuve égal aux points de vie restants du méchant afin de vaincre le stade actuel du méchant.",
  '61003': "Ténacité.\n<b>Action</b> : inclinez Luke Cage et infligez-lui 1 dégât → donnez-lui une carte d'état Tenace.",
  '61004': "<b>Action de héros</b> (<i>attaque</i>) : infligez 3 dégâts à un ennemi. Vous pouvez retirer 1 jeton Preuve d'Alias Investigations pour infliger 2 dégâts supplémentaires et faire gagner à cette attaque soit Déferlement, soit Perçant.",
  '61005': "<b>Réponse</b> : après qu'un jeton Preuve a été placé sur Alias Investigations, redressez votre identité. Mélangez cet événement dans votre deck.",
  '61006': "<b>Action d'alter ego</b> (<i>contre</i>) : retirez 4 menaces d'une manigance et placez 2 jetons Preuve sur Alias Investigations. Défaussez la carte du dessus du deck Rencontre. Si cette carte est un sbire ou une manigance annexe, révélez-la.",
  '61007': "Cette manigance ne compte pas dans la limite de manigances annexes de joueur.\n<b>Une fois déjouée</b> : le joueur qui a déjoué cette manigance pioche 3 cartes.",
  '61008': "<b>Action d'alter ego</b> : retirez 2 jetons Preuve d'Alias Investigation et inclinez Demander une Faveur → cherchez dans votre deck un allié et jouez-le comme s'il était dans votre main, en réduisant de 2 son coût en ressources. (<i>Mélangez</i>.)",
  '61009': "<b>Action d'alter ego</b> : inclinez cette carte et choisissez un sbire non-[[ÉLITE]].\nRetirez X jetons Preuve d'Alias Investigations, X étant égal au nombre de points de vie restants de ce sbire moins 2 → défaussez ce sbire.",
  '61010': "<b>Réponse</b> : après qu'un ennemi a été vaincu, inclinez Preuve Indirecte → placez 1 jeton Preuve sur Alias Investigations.",
  '61011': "Jessica Jones gagne +2 DEF.\n<b>Réponse</b> : après que vous avez défendu, placez 1 jeton Preuve sur Alias Investigations.",
  '61012': "<b>Réponse</b> (<i>attaque</i>) : après que le méchant s'est activé contre un joueur, si vous êtes sous forme d'alter ego, passez sous forme de héros. Infligez 5 dégâts au méchant et à chaque sbire engagé avec ce joueur. Défaussez cette amélioration.",
  '61013': "<b>Interruption de héros</b> (<i>défense</i>) : quand vous êtes censé subir au moins 3 dégâts d'une attaque, défaussez cette amélioration → prévenez tous les dégâts de cette attaque. Subissez 1 dégât.",
  '61014': "<b>Action</b> : si cette carte est dans votre zone de jeu, attachez-la à une manigance annexe Rencontre non-Permanent.\n<b>Interruption</b> : quand un personnage contre la manigance attachée, ce contre retire 2 menaces supplémentaires. Si ce contre déjoue la manigance attachée, placez 2 jetons Preuve sur Alias Investigations.",
  '61015': "<b>Réponse</b> : après que Captain Marvel est entrée en jeu, défaussez les 4 cartes du dessus de votre deck. Si vous défaussez une ressource [energy] imprimée, retirez 2 menaces d'une manigance. Si vous défaussez plus d'une ressource [energy] imprimée, désorientez également un ennemi.",
  '61016': "<b>Réponse</b> : après qu'un personnage que vous contrôlez a contré, placez 1 jeton Patte ici (jusqu'à un maximum de 8). Vous pouvez défausser Spider-Woman pour infliger 1 dégât à un ennemi pour chaque jeton Patte qui est sur elle.",
  '61017': "<b>Réponse</b> : après avoir joué Squirrel Girl de votre main, placez 1 jeton Écureuil sur elle pour chaque carte dans votre main (jusqu'à un maximum de 4).\n<b>Action</b> : retirez 1 jeton Écureuil de Squirrel Girl → retirez 1 menace d'une manigance.",
  '61019': "<b>Action d'alter ego</b> : choisissez un joueur pour qu'il cherche une manigance annexe de joueur dans son deck et l'ajoute à sa main.\n<b>Action de héros</b> (<i>contre</i>) : retirez 3 menaces d'une manigance annexe de joueur.",
  '61020': "<b>Une fois déjouée</b> : résolvez chacune des options suivantes :\n• Ignorez la prochaine phase du Méchant.\n• Attribuez à chaque joueur 1 carte Rencontre face cachée (<i>immédiatement</i>).\n• Le méchant ne peut pas subir de dégâts jusqu'au début de la prochaine phase du Méchant (<i>non ignorée</i>).",
  '61023': "Restreint.\n<b>Action de héros</b> : défaussez cette carte → effectuez un contre de base sans vous incliner (<i>même si vous êtes incliné</i>). Pour ce contre, votre héros gagne +1 CTR, ignore le mot-clé Patrouille et toutes les icônes de crise ([crisis]) en jeu.",
  '61024': "1 max par joueur.\n<b>Réponse d'alter ego</b> (<i>attaque</i>) : après que le méchant a manigancé, passez sous forme de héros et défaussez cette amélioration → infligez au méchant un nombre de dégâts égal à la quantité de menace placée par cette activation.",
  '61025': "Si votre identité a le trait [[DEFENDER]], cette carte gagne : « <b>Action</b> : mettez en jeu Hellcat depuis votre main. À la fin de la phase, défaussez-la. »",
  '61026': "Alliance.\n<b>Action</b> : choisissez :\n• Inclinez un alter ego [[CIVIL]] → redressez un héros ou un allié.\n• Inclinez un héros ou un allié → redressez un alter ego [[CIVIL]].",
  '61027': "En Équipe (<i>Jessica Jones et Luke Cage</i>). 1 max par deck.\n<b>Action de héros</b> (<i>contre</i>) : retirez 3 menaces d'une manigance. Soignez un total de 3 dégâts parmi Jessica Jones et Luke Cage.",
  '61028': "Victoire 0.\n<b>Une fois déjouée</b> : chaque joueur peut mélanger dans son deck toutes les cartes spécifiques à son identité de sa pile de défausse.",
  '61029': "[star] Entrave 1[per_hero].\nPrérequis ([[DEFENDER]]). Victoire 0.\n<b>Une fois déjouée</b> : chaque joueur peut chercher une carte En-Équipe dans son deck ou sa pile de défausse et l'ajouter à sa main. Jusqu'à la fin de la phase, réduisez de 1 le coût pour jouer chaque carte En Équipe.",
  '61030': "Donnez cette carte au joueur de Jessica Jones.\nEn tant que coût supplémentaire pour changer de forme, défaussez 1 carte de votre main.\n<b>Action d'alter ego</b> : choisissez :\n• Retirez de la partie un allié que vous contrôlez → retirez cette obligation de la partie.\n• Désorientez votre identité → défaussez cette obligation.",
  '61031': "[star] La MNG de l'Homme Pourpre est égale à la MNG ou CTR la plus élevée parmi les personnages en jeu. Son ATQ est égale à l'ATQ la plus élevée parmi les personnages en jeu.",
  '61032': "[star] Entrave 3[per_hero].\n<b>Une fois révélée</b> : placez 2 jetons Phéromone sur chaque obligation Suggestion qui est en jeu.\n<b>Réponse forcée</b> : après qu'une obligation Suggestion est entrée en jeu, placez 2 jetons Phéromone <i>(supplémentaires)</i> dessus.",
  '61033a': "Utilisations (3 jetons Phéromone).\n<b>Action forcée</b> : retirez 1 jeton Phéromone de cette carte et inclinez-la → choisissez : soit vous jouez une carte ayant une icône de ressource [energy] imprimée <i>(en payant ses coûts)</i>, soit vous ajoutez 2 menaces à la manigance principale.",
  '61033b': "Utilisations (3 jetons Phéromone).\n<b>Action forcée</b> : retirez 1 jeton Phéromone de cette carte et inclinez-la → choisissez : soit vous jouez une carte ayant une icône de ressource [mental] imprimée <i>(en payant ses coûts)</i>, soit vous ajoutez 2 menaces à la manigance principale.",
  '61033c': "Utilisations (3 jetons Phéromone).\n<b>Action forcée</b> : retirez 1 jeton Phéromone de cette carte et inclinez-la → choisissez : soit vous jouez une carte ayant une icône de ressource [physical] imprimée <i>(en payant ses coûts)</i>, soit vous ajoutez 2 menaces à la manigance principale.",
  '61034': "Départ. (<i>Vous pouvez ajouter cette carte à votre main avant de piocher votre main de départ.</i>)\nVotre héros gagne +1 ATQ.",
  '61035': "Jouez cette carte sous le contrôle de n'importe quel joueur. 1 max par joueur.\n<b>Réponse</b> : après que vous avez attaqué et vaincu exactement un sbire, inclinez Passage à Tabac → retirez d'une manigance une quantité de menaces égale à la MNG de base de ce sbire.",
  '61036': "Départ. (<i>Vous pouvez ajouter cette carte à votre main avant de piocher votre main de départ.</i>)\nVotre héros gagne +1 CTR.",
  '61037': "Départ. (<i>Vous pouvez ajouter cette carte à votre main avant de piocher votre main de départ.</i>)\nChaque allié que vous contrôlez gagne +1 point de vie.",
  '61038': "Diminuez de la DEF de votre héros la quantité de dégâts que subit Echo de chaque attaque ennemie.",
  '61039': "Victoire 0.\n<b>Une fois déjouée</b> : chaque joueur peut passer sous forme d'alter ego. Soignez chaque alter ego d'un nombre de dégâts égal à sa REC.",
  '61040': "Attachez cette amélioration à une carte. La carte attachée perd les icônes [acceleration], [amplify], [crisis] et [hazard].\n<b>Réponse forcée</b> : à la fin du round, chaque joueur peut dépenser 1 ressource de n'importe quel type. Si un joueur ne le fait pas, défaussez cette amélioration.",
  '62001a': "<i>Peau Impénétrable</i> — Luke Cage peut avoir n'importe quel nombre de cartes d'état Tenace. Les attaques contre Luke Cage perdent Perçant.\n<b>Réponse forcée</b> : après qu'une carte d'état Tenace a été défaussée de Luke Cage, il subit 1 dégât inéluctable <i>(ignorez les cartes d'état Tenace)</i>.",
  '62002': "[star] Jessica Jones gagne +1 CTR pour chaque carte d'état Tenace sur votre identité (jusqu'à un maximum de +4 CTR).",
  '62003': "<b>Action de héros</b> : donnez une carte d'état Tenace à Luke Cage. Pour chaque carte d'état Tenace sur Luke Cage, choisissez un personnage que vous contrôlez et redressez-le.",
  '62004': "<b>Action de héros</b> (<i>attaque</i>) : infligez 3 dégâts à un ennemi. Vous pouvez défausser une carte d'état Tenace de Luke Cage pour renvoyer cet événement dans votre main.",
  '62005': "<b>Action de héros</b> (<i>contre</i>) : donnez une carte d'état Tenace à Luke Cage. Retirez 1 menace d'une manigance pour chaque carte d'état Tenace sur Luke Cage (jusqu'à un maximum de 5).",
  '62006': "[star] Réduisez de 1 le coût pour jouer cette carte pour chaque carte d'état Tenace sur Luke Cage.\n<b>Action de héros</b> (<i>attaque</i>) : infligez 5 dégâts au méchant et à chaque sbire engagé avec vous.",
  '62007': "<b>Réponse</b> : après qu'une carte d'état Tenace a été défaussée d'un personnage [[Defender]], inclinez la Salle de Fogwell → redressez ce personnage.",
  '62008': "<b>Action d'alter ego</b> : inclinez l'Expérience de Burstein → donnez une carte d'état Tenace à Luke Cage (2 cartes d'état Tenace à la place s'il n'en a aucune).",
  '62009': "Attachez cette carte à un sbire. 1 max par sbire.\nLes attaques contre le sbire attaché infligent 2 dégâts supplémentaires et gagnent Déferlement.\n<b>Réponse</b> : après avoir joué cette carte, engagez le sbire attaché.",
  '62010': "Luke Cage gagne Riposte 1.\n<b>Interruption de héros</b> : quand n'importe quelle quantité de dégâts est censée être infligée à Luke Cage, inclinez le Bracelet Métallique → diminuez de 1 cette quantité de dégâts.",
  '62011': "<b>Réponse de héros</b> : après qu'une carte d'état Tenace a été défaussée de Luke Cage, inclinez Power Man → piochez une carte.",
  '62012': "<b>Interruption</b> : quand Iron Fist défend contre une attaque ennemie, prévenez un nombre de dégâts de cette attaque égal à l'ATQ d'Iron Fist.",
  '62013': "Ténacité.\n[star] Misty Knight gagne +2 ATQ et +2 CTR tant qu'elle a une carte d'état Tenace.",
  '62014': "Ténacité.\n<b>Interruption</b> : quand un autre allié est censé être vaincu, défaussez Valkyrie (<i>elle doit être en jeu</i>) → à la place, soignez cet allié jusqu'à ce qu'il ait 1 point de vie restant.",
  '62015': "<b>Réponse de héros</b> : après que votre héros a défendu, chaque allié que vous contrôlez gagne +1 CTR et +1 ATQ jusqu'à la fin de la phase des Joueurs.",
  '62018': "Utilisations (3 jetons Blocage).\n<b>Action</b> : retirez 1 jeton Blocage de cette carte et inclinez-la → donnez une carte d'état Tenace à un allié [[Defender]].",
  '62019': "Jouez cette carte sous le contrôle de n'importe quel joueur. 1 max par joueur.\nChaque personnage que vous contrôlez qui a exactement 1 point de vie restant gagne +2 CTR et +2 ATQ.",
  '62020': "Hulk gagne +1 ATQ pour chaque jeton Rage sur lui.\n<b>Réponse</b> : après que le méchant vous a attaqué, placez 1 jeton Rage sur cet allié.",
  '62021': "Ténacité.\n<b>Réponse</b> : après que Miss Hulk est entrée en jeu, donnez une carte d'état Tenace à votre identité.",
  '62022': "<b>Action</b> : cherchez dans votre deck ou votre pile de défausse une carte En Équipe ainsi qu'un allié désigné par le mot-clé En Équipe de cette carte. Ajoutez ces cartes à votre main. <i>(Mélangez.)</i>",
  '62023': "En Équipe <i>(Iron Fist et Luke Cage)</i>. 1 max par deck.\n<b>Action de héros</b> (<i>attaque</i>) : infligez 2 dégâts à un ennemi et donnez une carte d'état Tenace à un personnage.",
  '62024': "En Équipe (<i>Jessica Jones et Luke Cage</i>). 1 max par deck.\n<b>Action de héros</b> (<i>contre</i>) : retirez 3 menaces d'une manigance. Soignez un total de 3 dégâts parmi Jessica Jones et Luke Cage.",
  '62028': "<b><i>Donnez cette carte au joueur de Luke Cage.</i></b>\n<b>Réponse forcée</b> : après avoir terminé la phase des Joueurs, subissez 3 dégâts inéluctables (<i>ignorez les cartes d'état Tenace</i>).\n<b>Réponse d'alter ego</b> : après avoir récupéré, retirez Blessure Interne de la partie.",
  '62029': "[star] <b>Réponse forcée</b> : après que Cottonmouth a attaqué, il attaque le même personnage 2 fois supplémentaires. (Limite d'une fois par phase.)\n(<i>Sbire némésis de Luke Cage.</i>)\n\n[star] <b>Boost</b> : attribuez cette carte au joueur de Luke Cage en tant que carte Rencontre face cachée.",
  '62030': "Aucun sbire [[SOCIÉTÉ DU SERPENT]] ne peut être attaqué.\n<b>Une fois déjouée</b> : le joueur qui a déjoué cette manigance défausse des cartes du dessus du deck Rencontre jusqu'à ce qu'un sbire [[SOCIÉTÉ DU SERPENT]] soit défaussé, puis il le révèle.\n[star] <b>Boost</b> : vous êtes désorienté.",
  '62031': "Attachez cette carte à Cottonmouth. Sinon, attachez-la au méchant.\n[star] <b>Interruption forcée</b> : quand l'ennemi attaché attaque un personnage, défaussez chaque carte d'état Tenace du personnage attaqué.\n<b>Action de héros</b> : dépensez les ressources suivantes : [mental][mental] → défaussez cette carte.",
  '62032': "[star] <b>Réponse forcée</b> : après qu'Asp a manigancé contre vous, vous êtes sonné.\n[star] <b>Boost</b> : vous êtes sonné.",
  '62033': "Coup Rapide.\n<b>Interruption forcée</b> : quand Sidewinder est attaqué, défaussez la carte du dessus du deck Rencontre. Si la carte défaussée a une capacité « <b>Boost</b> », attribuez Sidewinder au joueur attaquant en tant que carte Rencontre face cachée.",
  '62034': "<b>Action de héros</b> (<i>attaque</i>) : infligez 3 dégâts à un ennemi (6 dégâts à la place si vous avez le trait [[GÉANT]] ou plus de points de vie restants que cet ennemi).",
  '62035': "<b>Action de héros</b> : le méchant manigance. Donnez une carte d'état Tenace à votre héros.",
  '62036': "<b>Réponse</b> : après avoir récupéré, si vos points de vie restants sont supérieurs ou égaux à vos points de vie de base, inclinez cette amélioration → donnez à votre identité une carte d'état Tenace.",
  '62037': "Jouez cette carte uniquement si n'importe quel joueur contrôle une carte [[ARTISTE MARTIAL]].\nAttachez cette carte à un personnage ami. 1 max par personnage.\nLe personnage attaché gagne +1 point de vie et le trait [[ARTISTE MARTIAL]].",
}
